"""Fixed CFA masks versus RGB residual energy, without pixel interventions."""
from datetime import datetime,timezone
import json
from pathlib import Path

import numpy as np
from scipy.ndimage import maximum_filter

from measure_noise_opening_stages import read_crops
from study_noise_neighbourhoods import ROOT,sha256,git


RADII=(0,1,2,4)
SHIFTS=((0,32),(32,0),(32,32))


def mosaic_mask(selections):
    mask=np.zeros((128,128),dtype=bool)
    for item in selections:
        phase=item['phase']
        if phase not in range(4):raise ValueError('Invalid CFA phase')
        dy,dx=divmod(phase,2)
        for site in item['selected']:
            y,x=site['y'],site['x']
            if not 0<=y<64 or not 0<=x<64:raise ValueError('Invalid CFA coordinate')
            mask[2*y+dy,2*x+dx]=True
    return mask


def regions(mask):
    if mask.shape!=(128,128):raise ValueError('Need128 square mask')
    result=[];previous=np.zeros_like(mask)
    for radius in RADII:
        cumulative=maximum_filter(mask,size=2*radius+1,mode='constant',cval=0).astype(bool)
        result.append((radius,cumulative,cumulative&~previous));previous=cumulative
    return result


def energy(a,b,mask):
    a,b=np.asarray(a,dtype=float),np.asarray(b,dtype=float)
    if a.shape!=(128,128,3) or b.shape!=a.shape or mask.shape!=(128,128) or not np.isfinite(a).all() or not np.isfinite(b).all():raise ValueError('Finite matching128 RGB required')
    d=(a-b)/np.sqrt(2.);d-=d.mean(axis=(0,1));v2=d*d;v4=v2*v2
    s2=v2.sum(axis=(0,1));s4=v4.sum(axis=(0,1))
    if np.any(s2<=0):raise ValueError('Positive moments required')
    area=float(mask.mean());second=v2[mask].sum(axis=0)/s2;fourth=v4[mask].sum(axis=0)/s4
    return dict(pixels=int(mask.sum()),area_fraction=area,second_moment_share=second.tolist(),fourth_moment_share=fourth.tolist(),
        second_moment_enrichment=(second/area).tolist() if area else None,
        fourth_moment_enrichment=(fourth/area).tolist() if area else None)


def run():
    start=datetime.now(timezone.utc);stamp=start.strftime('%Y%m%dT%H%M%SZ');base=ROOT/'docs/validation/raw'
    paths=[base/n for n in ('sites-recurrents-bruit-v001-20261028T115520Z.json','repetabilite-distributions-noirs-v001-20261028T114512Z.json')]
    hashes=[sha256(p) for p in paths];sites,repeat=[json.loads(p.read_text(encoding='utf-8')) for p in paths]
    frozen_selection=Path(sites['freeze']['path'])
    if sha256(frozen_selection)!=sites['freeze']['sha256']:raise ValueError('Selected coordinates changed')
    selections=json.loads(frozen_selection.read_text(encoding='utf-8'))['selections']
    freeze=base/f'gel-voisinages-sites-bruit-v001-{stamp}.json'
    policy=dict(campaign_id='noise-site-neighborhoods-freeze-'+stamp,schema_version=1,data_version=1,measured_at_utc=start.isoformat(),parents=[dict(path=str(p),sha256=h) for p,h in zip(paths,hashes)],radii=list(RADII),shifts=list(SHIFTS),
        policy='Unchanged development-only CFA site masks from previous frozen selection. Union phases in128 native grid; Chebyshev radii0/1/2/4 clipped at crop border, cumulative and disjoint annuli. Three fixed toroidal shifts of each REGION after dilation preserve area exactly, descriptive controls not calibrated null samples. Measure centered RGB paired residual second/fourth moment shares and area-normalized concentration after RCD,final camera,DCP for all30 ROIs, roles retained. No pixel removal, optimization, causality claim, RAW decode, simulation replay or production change.',
        source=Path(__file__).read_text(encoding='utf-8'),source_sha256=sha256(Path(__file__)))
    with freeze.open('x',encoding='utf-8') as h:json.dump(policy,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('FROZEN',freeze,flush=True)
    masks={(iso,roi):mosaic_mask([s for s in selections if s['iso']==iso and s['roi']==roi]) for iso in (1600,51200) for roi in range(3)}
    cached={}
    for source,item in repeat['native'].items():
        if sha256(Path(item['path']))!=item['sha256'] or sha256(Path(item['pixels']['path']))!=item['pixels']['sha256']:raise ValueError('Native pixels changed')
        cached[source]=read_crops(Path(item['pixels']['path']),item['record'])
    records=[]
    for pair in repeat['records']:
        roi=pair['roi'];mask=masks[(pair['iso'],roi)];stages={}
        for stage in ('post_rcd_median_camera_rgb','pre_dcp_camera_rgb','post_dcp_rec2020'):
            a,b=[cached[p][stage][roi][64:192,64:192] for p in pair['paths']]
            scores=[]
            for radius,cumulative,annulus in regions(mask):
                entry=dict(radius=radius)
                for name,region in (('cumulative',cumulative),('annulus',annulus)):
                    entry[name]=dict(selected=energy(a,b,region),shifted=[dict(shift=list(shift),score=energy(a,b,np.roll(region,shift,axis=(0,1)))) for shift in SHIFTS])
                scores.append(entry)
            stages[stage]=scores
        records.append(dict(pair_index=pair['pair_index'],iso=pair['iso'],roi=roi,subset=pair['subset'],paths=pair['paths'],seed_sites=int(mask.sum()),stages=stages))
    if len(records)!=30 or hashes!=[sha256(p) for p in paths]:raise ValueError('Coverage/provenance failure')
    now=datetime.now(timezone.utc);out=base/f'voisinages-sites-bruit-v001-{now.strftime("%Y%m%dT%H%M%SZ")}.json'
    result=dict(campaign_id='noise-site-neighborhoods-'+stamp,schema_version=1,data_version=1,started_at_utc=start.isoformat(),measured_at_utc=now.isoformat(),completed_at_utc=now.isoformat(),parents=policy['parents'],freeze=dict(path=str(freeze),sha256=sha256(freeze)),records=records,
        units='Native pixel Chebyshev distance; dimensionless area and moment shares/enrichment. RGB channels, not CFA phases.',
        limitations='Association with outcome, not counterfactual causal contribution. Frozen masks selected on development; prior inspection of control still limits blindness. Toroidal shifted controls can overlap sites and introduce wrapping; deterministic descriptive references, no pvalues. Crop border truncates neighborhoods, union of phases not channel-specific. No pixel modification, denoising or visual quality validation; same dark session only.',verdict='frozen_site_spatial_association_not_causal_correction',commit=git('rev-parse','HEAD'))
    with out.open('x',encoding='utf-8') as h:json.dump(result,h,ensure_ascii=False,indent=1,allow_nan=False)
    print('RESULT',out,flush=True)


if __name__=='__main__':run()
